export const Overview = () => {
  const [isBodyExpanded, setIsBodyExpanded] = useState(false);
  const { token } = useContext(UserContext);
  const githubService = new GithubService(token);

  const { pullRequestDetail, pullRequestMetaData, refreshPrData } = useContext(
    PullRequestContext
  );

  const submitReview = async (
    body: string,
    event: LeaveReviewEvent
  ): Promise<void> => {
    if (pullRequestDetail) {
      githubService
        .submitReview(
          pullRequestDetail.repoOwner,
          pullRequestDetail.repoName,
          pullRequestDetail.number,
          body,
          event
        )
        .then(() => {
          refreshPrData();
        });
    }
  };

  return (
    <>
      {pullRequestMetaData ? (
        <>
          <Box
            position="sticky"
            top={0}
            zIndex={5}
            id="overview-header-bar"
            backgroundColor="palette.neutral.800"
            pt="20px"
            pb="10px"
          >
            <HStack justify="space-between">
              <Text fontSize="22px" fontWeight="700" pl="2px">
                {pullRequestMetaData.title}
              </Text>
              <Flex gap={3} direction="column" alignItems="end">
                <Flex gap={3}>
                  <PrState />
                  <OpenInGithub />
                  <LeaveReviewButton submit={submitReview} />
                  <MergeButton
                    mergeable={
                      (pullRequestMetaData.mergeable &&
                        pullRequestMetaData.mergeable_state !== "blocked") ??
                      false
                    }
                  />
                </Flex>
              </Flex>
            </HStack>
            {pullRequestDetail?.commits !== undefined ? (
              <CommitStacks commits={pullRequestDetail.commits} />
            ) : null}
          </Box>
          <Flex
            width="100%"
            direction="column"
            backgroundColor="palette.neutral.600"
            borderRadius={ComponentConstants.COMPONENT_BOX_RADIUS}
            onClick={() => setIsBodyExpanded(!isBodyExpanded)}
            marginBottom="10px"
            marginTop="1px"
            borderColor="brand.greyBorder"
            borderWidth="1px"
            overflow="hidden"
            boxSizing="border-box"
            cursor={!isBodyExpanded ? "pointer" : undefined}
          >
            <Flex
              cursor="pointer"
              width="100%"
              borderBottomColor="brand.greyBorder"
              borderBottomWidth="1px"
              py="15px"
              px="15px"
              justifyContent="space-between"
            >
              <HStack>
                <UserAvatar
                  avatarUrl={pullRequestMetaData?.user?.avatar_url ?? ""}
                />
                <Text fontWeight={700}>{pullRequestMetaData?.user?.login}</Text>
              </HStack>
              <HStack>
                <Reviewers />
              </HStack>
            </Flex>
            <Text
              px="35px"
              py="10px"
              noOfLines={!isBodyExpanded ? 3 : undefined}
              maxHeight={!isBodyExpanded ? "150px" : undefined}
              overflowY="hidden"
            >
              <MarkdownText>
                {pullRequestMetaData.body ?? "[No Body]"}
              </MarkdownText>
            </Text>
            <Flex
              cursor="pointer"
              width="100%"
              borderTopColor="brand.greyBorder"
              borderTopWidth="1px"
              py="8px"
              px="8px"
              justifyContent="center"
            >
              {isBodyExpanded ? (
                <AiOutlineUp display="inline-block" />
              ) : (
                <AiOutlineDown display="inline-block" />
              )}
            </Flex>
          </Flex>
        </>
      ) : null}
    </>
  );
};
